 40 | impl SessionValues {
 41 |     /// Load every value from the session, resolving latest-wins and dropping
 42 |     /// tombstoned keys.
 43 |     pub async fn load(session: &Session) -> SessionResult<Self> {
 44 |         let entries = session
 45 |             .find_entries(&EntryQuery {
 46 |                 entry_type: Some("custom"),
 47 |                 custom_type: Some(VALUE_CUSTOM_TYPE.to_string()),
 48 |                 order: Some(EntryOrder::OldestFirst),
 49 |                 limit: None,
 50 |                 cursor: None,
 51 |             })
 52 |             .await?;
 53 |         Ok(Self::from_entries(&entries))
 54 |     }
 55 | 
 56 |     /// Resolve a value set from already-fetched entries (oldest first).
 57 |     pub fn from_entries(entries: &[Entry]) -> Self {
 58 |         let mut values = BTreeMap::new();
 59 |         for entry in entries {
 60 |             let Entry::Custom(custom) = entry else {
 61 |                 continue;
 62 |             };
 63 |             if custom.custom_type != VALUE_CUSTOM_TYPE {
 64 |                 continue;
 65 |             }
 66 |             let Some(data) = &custom.data else {
 67 |                 continue;
 68 |             };
 69 |             let Some(key) = data.get("key").and_then(Value::as_str) else {
 70 |                 continue;
 71 |             };
 72 |             match data.get("value") {
 73 |                 // Tombstone: delete from this point forward.
 74 |                 Some(Value::Null) | None => {
 75 |                     values.remove(key);
 76 |                 }
 77 |                 Some(value) => {
 78 |                     values.insert(key.to_string(), value.clone());
 79 |                 }
 80 |             }
 81 |         }
 82 |         Self { values }
 83 |     }
 84 | 
 85 |     /// Read a value.
 86 |     pub fn get(&self, key: &str) -> Option<&Value> {
 87 |         self.values.get(key)
 88 |     }
 89 | 
 90 |     /// Read a typed value, returning `None` when absent or the wrong shape.
 91 |     pub fn get_as<T: serde::de::DeserializeOwned>(&self, key: &str) -> Option<T> {
 92 |         let value = self.values.get(key)?;
 93 |         serde_json::from_value(value.clone()).ok()
 94 |     }
 95 | 
 96 |     /// Every live key/value pair, ordered by key.
 97 |     pub fn iter(&self) -> impl Iterator<Item = (&str, &Value)> {
 98 |         self.values.iter().map(|(k, v)| (k.as_str(), v))
 99 |     }
